15	/// The outcome of staging one op.
16	#[derive(Debug, Clone, PartialEq, Eq)]
17	pub enum StageOutcome {
18	    /// The op was journaled; on a content op its bytes were staged too.
19	    Queued {
20	        /// The durable op-queue id.
21	        op_id: OpId,
22	    },
23	    /// A content upload would exceed the profile staging budget: it fails fast
24	    /// and **nothing** is journaled or staged (the mutation did not happen).
25	    RejectedOverBudget {
26	        /// Staged bytes already held.
27	        staged: u64,
28	        /// The upload's own byte length.
29	        incoming: u64,
30	        /// The profile budget.
31	        budget: u64,
32	    },
33	}
