35	/// Stage one op. Metadata ops (no upload bytes) always enqueue, regardless of
36	/// budget. A content op is fail-fast: if staged-total + its bytes would exceed
37	/// the budget, nothing is written; otherwise the bytes are staged under the
38	/// op's staging key and the op is enqueued.
39	///
40	/// `upload` is the **already-sealed** content payload (core's content-seal runs
41	/// upstream in the content plane); no plaintext user content ever lands in the
42	/// staging store at rest.
43	///
44	/// Fail-fast ordering: the budget is checked and the bytes staged **before**
45	/// the op is enqueued, so a rejected upload leaves no dangling queue entry and
46	/// an accepted one leaves no op referencing unstaged bytes.
47	pub async fn stage_op<S: StagingStore>(
48	    store: &S,
49	    profile: &SyncTimingProfile,
50	    op: &Op,
51	    upload: Option<&[u8]>,
52	) -> SeamResult<StageOutcome> {
53	    match (op.staging_key(), upload) {
54	        (Some(key), Some(bytes)) => {
55	            let staged = store.staged_bytes_total().await?;
56	            let incoming = bytes.len() as u64;
57	            // Saturating: an overflowing sum is unreachable under any real
58	            // budget, and must still read as "over budget", never wrap to a
59	            // spuriously-small total.
60	            if staged.saturating_add(incoming) > profile.staging_budget_bytes {
61	                return Ok(StageOutcome::RejectedOverBudget {
62	                    staged,
63	                    incoming,
64	                    budget: profile.staging_budget_bytes,
65	                });
66	            }
67	            store.put_staged_bytes(key, bytes).await?;
68	            let op_id = store.enqueue_op(&op.encode()).await?;
69	            Ok(StageOutcome::Queued { op_id })
70	        }
71	        // A content op (staging key present) with no bytes is a broken caller
72	        // contract: journaling it would leave a durable op referencing content
73	        // that was never staged. Fail closed — enqueue nothing.
74	        (Some(_), None) => Err(SeamError::new(
75	            "stage_op: content op carries a staging key but no upload bytes",
76	        )),
77	        // A metadata op (no staging key): journal unbounded.
78	        (None, _) => {
79	            let op_id = store.enqueue_op(&op.encode()).await?;
80	            Ok(StageOutcome::Queued { op_id })
81	        }
82	    }
83	}
