85	/// Staging keys held by the store that no queued op references — orphan
86	/// residue from a rejected or superseded upload, safe to GC (#33 D6 staged-
87	/// bytes hygiene).
88	pub async fn orphan_staging_keys<S: StagingStore>(store: &S) -> SeamResult<Vec<Vec<u8>>> {
89	    let queued = store.queued_ops().await?;
90	    let mut referenced = std::collections::HashSet::new();
91	    for (_, bytes) in &queued {
92	        match Op::decode(bytes) {
93	            Ok(op) => {
94	                if let Some(key) = op.staging_key() {
95	                    referenced.insert(key.to_vec());
96	                }
97	            }
98	            // An undecodable entry dead-letters with its staged bytes preserved
99	            // (#33 D6); its staging key is unknowable, so nothing is safely an
100	            // orphan this pass — fail closed.
101	            Err(_) => return Ok(Vec::new()),
102	        }
103	    }
104	    let orphans = store
105	        .staged_keys()
106	        .await?
107	        .into_iter()
108	        .filter(|key| !referenced.contains(key))
109	        .collect();
110	    Ok(orphans)
111	}
