69	/// Frame `plaintext` into fixed-size chunks and seal each under `key`
70	/// (blueprint/engine.md "Content plane"). Every chunk but the last carries
71	/// exactly `profile.chunk_size` plaintext bytes; empty input frames to a single
72	/// empty leaf so every version has at least one addressable block.
73	///
74	/// Each chunk draws a fresh nonce from injected `entropy` — XChaCha20-Poly1305
75	/// nonce reuse under one key is a break, and the nonce is public (core prefixes
76	/// it into the sealed blob). Deterministic under a fixed key and a seeded
77	/// entropy stream: the leaf CIDs and sealed bytes are byte-identical run to run.
78	pub fn frame_and_seal(
79	    plaintext: &[u8],
80	    key: &ContentKey,
81	    entropy: &mut impl Entropy,
82	    profile: &ContentProfile,
83	) -> Result<Vec<SealedChunk>, EntropyError> {
84	    let framed: Vec<&[u8]> = if plaintext.is_empty() {
85	        vec![&[][..]]
86	    } else {
87	        plaintext.chunks(profile.chunk_size()).collect()
88	    };
89	    let mut leaves = Vec::with_capacity(framed.len());
90	    for chunk in framed {
91	        let mut nonce = [0u8; NONCE_LEN];
92	        entropy.fill(&mut nonce)?;
93	        let sealed = seal_chunk(key.as_bytes(), &nonce, chunk);
94	        let cid = compute_cid(CONTENT_CID_CODEC, &sealed);
95	        leaves.push(SealedChunk { cid, sealed });
96	    }
97	    Ok(leaves)
98	}
